scripts.linear_congruence:
def solve(inputs: dict) -> float:
    s = inputs['SEED']
    a = inputs['A']
    b = inputs['B']
    m = inputs['M']
    k = inputs['K']

    for i in range(k):
        s = (a * s + b) % m

    return float(s)

scripts.count_inversions:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']
    n = len(values)
    count = 0

    # Count all pairs (i, j) where i < j but values[i] > values[j]
    for i in range(n):
        for j in range(i + 1, n):
            if values[i] > values[j]:
                count += 1

    return float(count)

scripts.find_gcd:
def solve(inputs: dict) -> float:
    from math import gcd
    from functools import reduce

    values = inputs['VALUES']
    result = reduce(gcd, values)

    return float(result)

scripts.luhn_procedure:
def solve(inputs: dict) -> float:
    n = str(inputs['N'])
    digits = [int(d) for d in n]

    # Reverse to process from right to left
    digits.reverse()

    total = 0
    for i, digit in enumerate(digits):
        if i % 2 == 1:  # Every second digit (0-indexed, so odd indices)
            doubled = digit * 2
            if doubled > 9:
                doubled -= 9
            total += doubled
        else:
            total += digit

    return float(total)

scripts.factorial_mod:
def solve(inputs: dict) -> float:
    n = inputs['N']
    mod = inputs['MOD']

    result = 1
    for i in range(1, n + 1):
        result = (result * i) % mod

    return float(result)

